def aplicar(sits):
    """Acrescenta os perfis às fichas comuns e junta as fichas próprias."""
    por_id = {s['id']: s for s in sits}
    for id_ in COMUNS:
        por_id[id_]['perfis'] = por_id[id_]['perfis'] + list(AMBOS)
    return sits + SITUACOES
